/* Edexcel IGCSE Geography past paper questions — Hazardous Environments (Question 3). Login-protected (served under /igcse). */
window.SBL_IGCSE_PPQ = {"topic": "Hazardous Environments", "img": "/igcse/geography/learn/past-papers-img/", "lessons": {"IGHZ01": {"n": 1, "title": "What is a hazard?", "href": "/igcse/geography/learn/hazardous-environments/l01-what-is-a-hazard"}, "IGHZ02": {"n": 2, "title": "Structure of the Earth", "href": "/igcse/geography/learn/hazardous-environments/l02-structure-of-the-earth"}, "IGHZ03": {"n": 3, "title": "Plate boundaries", "href": "/igcse/geography/learn/hazardous-environments/l03-plate-boundaries"}, "IGHZ04": {"n": 4, "title": "Earthquakes", "href": "/igcse/geography/learn/hazardous-environments/l04-earthquakes"}, "IGHZ05": {"n": 5, "title": "Earthquake hazards and tsunamis", "href": "/igcse/geography/learn/hazardous-environments/l05-earthquake-hazards-and-tsunamis"}, "IGHZ06": {"n": 6, "title": "Earthquake management", "href": "/igcse/geography/learn/hazardous-environments/l06-earthquake-management"}, "IGHZ07": {"n": 7, "title": "Earthquake case study (HIC): Japan 2011", "href": "/igcse/geography/learn/hazardous-environments/l07-japan-2011-earthquake"}, "IGHZ08": {"n": 8, "title": "Earthquake case study (LIC): Haiti 2010", "href": "/igcse/geography/learn/hazardous-environments/l08-haiti-2010-earthquake"}, "IGHZ09": {"n": 9, "title": "Volcanoes", "href": "/igcse/geography/learn/hazardous-environments/l09-volcanoes"}, "IGHZ10": {"n": 10, "title": "Volcano case study: Mount Kīlauea 2018", "href": "/igcse/geography/learn/hazardous-environments/l10-kilauea-2018"}, "IGHZ11": {"n": 11, "title": "Tropical storms", "href": "/igcse/geography/learn/hazardous-environments/l11-tropical-storms"}, "IGHZ12": {"n": 12, "title": "Tropical storm case study: Typhoon Haiyan 2013", "href": "/igcse/geography/learn/hazardous-environments/l12-typhoon-haiyan-2013"}}, "parts": [{"key": "2024-3a", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify the plate boundary where volcanoes do not form.", "intro": "", "options": [["A", "conservative (transform)"], ["B", "constructive (divergent)"], ["C", "destructive (convergent)"], ["D", "hotspot"]], "answer": "A", "type": "mcq", "lesson": "IGHZ03", "ms": "AO1 (1 mark) (1)\nA (conservative)\n\nAnswer cannot be B (shield volcanoes), C (composite volcanoes), D (hotspot/shield volcanoes)", "sources": []}, {"key": "2024-3bi", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify the correct way to measure tropical cyclone intensity.", "intro": "", "options": [["A", "Mercalli scale"], ["B", "Moment magnitude scale"], ["C", "Richter scale"], ["D", "Saffir-Simpson scale"]], "answer": "D", "type": "mcq", "lesson": "IGHZ11", "ms": "AO1 (1 mark) (1)\n\nD (Saffir-Simpson Scale)\nAnswer cannot be A (earthquakes), B (earthquakes), C (earthquakes).", "sources": []}, {"key": "2024-3bii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one characteristic of a tropical cyclone.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark) (1)\nAward one mark for any of the following:\n\n• Eye (1)\n• Eye wall (1)\n• Spiralling / rotating clouds (1)\n• Banks of thunderstorms / heavy rainfall (1)\n• Strong winds (1)\n• Low pressure (1)\n\nAccept any other appropriate response.", "sources": []}, {"key": "2024-3biii", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(b)(iii)", "marks": 2, "text": "Explain one reason tropical cyclones lose their energy when they reach land.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO2 (2 marks) (2)\n\nAward 1 mark for initial explanation and a further mark for development up to a maximum of two marks.\n• Tropical storms source of energy comes from warm ocean water (1) as this fuels high evaporation rates(1).\n• On land tropical storms lose their energy source (1) which means their energy dissipates shortly after landfall (1).\n• On land there is increased friction (1) which alters the flow of air (1).\nAccept any other appropriate response.", "sources": []}, {"key": "2024-3c", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(c)", "marks": 4, "text": "Explain two reasons preparation for earthquakes may be more effective in some countries than others.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO1 (2 marks)/AO2 (2 marks) (4)\nAward 1 mark (AO1) for identifying a preparation strategy and a further mark explanation (AO2) up to a maximum of two marks each.\n\n• Evacuation routes (1) are often clearly sign posted making people aware of where to go (1).\n• Many people have access to mobile phones (1) which makes it easy to warn everyone (1).\n• Earthquake resistant buildings (1) meaning buildings are less likely to collapse (1).\n• People are likely to have ‘earthquake kits’ (1) meaning they often have food and water supplies prepared (1).\n• People living near plate boundaries are more aware of risk (1) so have emergency supplies prepared (1).\n\nAccept any other appropriate response.", "sources": []}, {"key": "2024-3d", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(d)", "marks": 3, "text": "Explain one physical factor that can make people more vulnerable to natural hazards.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ01", "ms": "AO2 (3 marks) (3)\nAward 1 mark for the initial explanation and 2 marks for further explanation up to a maximum of 3 marks.\n\n• Places near steep slopes (1) are more vulnerable as there is greater risk of landslides / lahars (1) increasing damage (1).\n• Clayey soil (1) increases risk of liquefaction (1) which damages buildings (1).\n• Coastal areas (1) are more at risk from tsunamis / tropical cyclones (1) increasing frequency of hazardous events (1).\n• Time of year (1) can cause more death (1) if it’s very hot or very cold when people are homeless (1).\n• Time of day (1) can increase injury/death (1) as at night people are in bed and less ready to escape (1).\n• Magnitude / size / strength (1) can increase risk as the winds / ground shaking are stronger (1) causing more damage to infrastructure (1).\nAccept any other appropriate response.", "sources": []}, {"key": "2024-3e", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(e)", "marks": 1, "text": "Study Figure 3a in the Resource Booklet. Identify the volcanic hazard labelled X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO3 (1 mark) (1)\n\nAward one mark for the following:\n• Lava (flow) (1)", "sources": [{"src": "2024-q3-p40.jpg", "figs": ["3a"]}]}, {"key": "2024-3f", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(f)", "marks": 4, "text": "Study Figure 3b in the Resource Booklet. Suggest two reasons for the distribution of volcanoes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO2 (2 marks)/AO3 (2 marks) (4)\n\nAward 1 mark (AO3) for the identification of a reason based on specific locational evidence from resource and a further mark for explanation (AO2) up to a maximum of two marks each.\n• Volcanoes are mainly found along the Pacific Plate boundary (1) because tectonic plate is being destroyed (1).\n• Some volcanoes are found in the middle of the Pacific Plate forming hotspots (1) because this area of crust is thin (1).\n• Some volcanoes are found away from the African Plate boundary (1) because plumes of hot magma rise through weak points on the Earth’s crust (1).\n• Most volcanoes are found around the Pacific Ocean (1) because of destructive/convergent plate boundaries/margins (1).\n• There volcanoes found around Iceland (1) because they are formed at constructive/divergent plate boundaries/margins (1).\n• Volcanoes are found in Hawaii (1) as a magma plume sits beneath the Pacific Plate (1).\n\nDo not credit ‘close to plate boundary’ without specific locational reference to evidence shown on the resource.\nAccept any other appropriate response.", "sources": [{"src": "2024-q3-p41.jpg", "figs": ["3b"]}]}, {"key": "2024-3g", "paper": "2024", "paperLabel": "June 2024 · Paper 1", "q": 3, "id": "3(g)", "marks": 8, "text": "Study Figure 3c in the Resource Booklet. Analyse the impacts of the volcanic eruption on the environment. You must refer to the resource in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO3 (4 mark)/AO4 (4 mark) (8)\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about analysing the significance of different types of impacts volcanic eruptions can have on the environment. Candidates will need to be able to identify the different types of impacts and consider the most severe impact for the environment.\n\nAO3\n• Shorter term impacts often last for hours, days, weeks.\n• Longer term impacts often last for months, years, decades.\n• A range of volcanic hazards can cause damage to the environment. Lava flows, lahars, pyroclastic flows can destroy vegetation and pollute rivers, lakes and waterways.\n• Ash and gas can make the air dangerous to breathe leading to the death of animals.\n• Animals can also ingest ash that has landed on vegetation they eat and water they drink.\n• In large eruptions ash can cause a drop in temperature as it blocks out solar radiation. This also increases the amount of sulfate aerosols in the atmosphere which absorb solar radiation radiated from the Earth’s surface increasing the cooling effect.\n• After the initial destruction the environment is able to rebalance, and the ash is a good fertiliser for the soil.\n\nAO4\n• Figure 3c shows a large area of vegetation was lost directly around the Mount Mayon.\n• Figure 3c shows there is a large area of green on the south flank of the volcano.\n• Figure 3c shows 29 rivers were silted up with ash reducing the water quality.\n• Figure 3c shows animals are impacted as a result of polluted rivers/swamps.\n• Figure 3c shows ash covers everything for large areas after the eruption.\n• Figure 3c shows 7,100 hectares of agricultural land was destroyed.\n• Figure 3c shows the area highly prone to ashfall was over 7km in width.\n• Figure 3c shows the areas more highly prone to ashfall were to the west, south and north of the volcano.\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2024-q3-p42.jpg", "figs": ["3c"]}]}, {"key": "2023-3a", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify the hazard often associated with earthquakes.", "intro": "", "options": [["A", "landslide"], ["B", "volcanic bombs"], ["C", "heavy rain"], ["D", "high wind speeds"]], "answer": "A", "type": "mcq", "lesson": "IGHZ05", "ms": "AO1 (1 mark)\nA Landslide (1)\n\nThe answer cannot be B (associated with volcanoes), C or D (associated with tropical cyclones).\n(1)", "sources": []}, {"key": "2023-3bi", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify the statement that best defines a constructive plate margin.", "intro": "", "options": [["A", "tectonic plates collide"], ["B", "tectonic plates move towards each other"], ["C", "tectonic plates pull apart"], ["D", "tectonic plates move alongside each other"]], "answer": "C", "type": "mcq", "lesson": "IGHZ03", "ms": "AO1 (1 mark)\n\nC Tectonic plates that pull apart (1).\nThe answer cannot be A (collision), B (collision, destructive), or D (conservative).\n(1)", "sources": []}, {"key": "2023-3bii", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "Define the term hot spot.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ10", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable definition of hotspot.\n\n• An area of tectonic activity away from a plate margin (1).\n\n• Magma plumes that create volcanoes in areas of thin crust (1).\n\n• Magma plume hotter than surrounding magma (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "2023-3c", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(c)", "marks": 2, "text": "Explain one way people can prepare for earthquakes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for identification of correct impact suitable way and a further mark for explanation (AO2) up to a maximum of two marks.\n• Earthquake drills (in schools) (1) to ensure people know how to respond to earthquakes (1).\n• Governments to send out leaflets (1) to ensure people know where to shelter during an earthquake (1).\n• Emergency service drills (1) to try and reduce the number of lives lost during an earthquake event (1).\n• Building earthquake-proof buildings (1) to reduce the number that collapse (1).\n• Secure furniture (to walls/floor) (1) to reduce risk of injury (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2023-3d", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(d)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Suggest two reasons why tropical cyclones can cause damage.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any reason and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• High wind speeds (up to 252kph) (1) can lead to damage to buildings and infrastructures (1).\n\n• Heavy rainfall that are associated with tropical cyclones (1) can cause flooding (1).\n\n• Strong winds (at Category 3 and above) (1) can cause storm surges (1) which can flood coastlines (1).\n\n• Vegetation might be damaged (1) at wind speeds above 178km (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2023-q3-p38.jpg", "figs": ["3a"]}]}, {"key": "2023-3e", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(e)", "marks": 3, "text": "Explain one reason why emergency aid can be important for responding to earthquake events.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO2 (3 marks)\n\nAward 1 mark for the identification of a suitable reason and 2 marks for further explanation up to a maximum of 3 marks.\n\nCandidates could identify:\n• Emergency aid can respond to short-term impacts of earthquakes (1) including providing immediate medical care and equipment for those injured (1) which can reduce the number of deaths (1).\n• Emergency aid such as provision of shelters can help reduce long-term impacts (1) such as homelessness (1) and can help people rebuild their lives (1).\n• Emergency aid in the form of financial support can help local areas get services active again (1) so have all the essential services they need (1) and so can reduce risks of death and illness (1).\nAccept any other appropriate response.\nNo credit for just identifying an emergency aid strategy\n\n(3)", "sources": []}, {"key": "2023-3f", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(f)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify the feature shown at X.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Eye (1)\n\n(1)", "sources": [{"src": "2023-q3-p39.jpg", "figs": ["3b"]}]}, {"key": "2023-3g", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(g)", "marks": 4, "text": "Explain two hazards associated with volcanic eruptions.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO1 (2 marks) AO2 (2 marks)\nAward 1 mark for initial point (AO1), a further mark (AO2) for the extension of this point up to maximum of 2 marks.\n\n• Volcanoes can eject a mix of hot steam, ash rock and dust (1) which can form pyroclastic flows which can travel at high speeds (1).\n• Volcanoes can eject ash (1) which can cover things causing a lot of damage / respiratory problems (1).\n• Lava flows (1) can damage buildings / habitats (1).\n• If volcanic ash mixes with rainfall or meltwater lahars can form (1) which can set as hard as cement (1).\n• Pyroclastic flows (1) can incinerate buildings / infrastructure (1).\n• Volcanic eruptions can causes earthquakes (1) which can damage houses (1).\n• Volcanic eruptions can cause landslides (1) which can cause injury / death (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2023-3h", "paper": "2023", "paperLabel": "June 2023 · Paper 1", "q": 3, "id": "3(h)", "marks": 8, "text": "Study Figure 3c and Figure 3d in the Resource Booklet. Analyse possible reasons why some countries are more vulnerable to the impact of earthquakes. Refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ01", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nNote to examiners: There was a minor error in the key on Figure 3c, an erratum was read out to candidates at the start of the exam and individually included with the Resource booklet. The sequence in the resource booklet reads:\n<5, 5-24, 24-50, 50> It should read:\n<5, 5-24, 25-50, >50\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about analysing why some countries are more vulnerable to the impact of natural hazards.\nAO3\n• There are a range of primary/immediate and secondary/long term impacts of earthquakes which can vary due to the size and intensity of the earthquake as well as the location. But these are likely to occur at plate margins (with the exception of hot spots).\n• A countries economic development may allow it to reduce people’s vulnerability to the impact of natural hazards. For example, in California many buildings are reinforced so they are less likely to collapse during an earthquake events, which should lead to fewer deaths.\n• Developing countries that are located on plate margins may not have the capability of preparing or preventing hazard events from occurring to the same extent as developed countries.\n• In many cases the physical factors are also significant for example in Mexico City the risk of liquefaction due to the soils the city is built on makes it more vulnerable to severe damage if an earthquake occurs.\n\nAO4\n• Fig 3c shows a map of average annual number people killed by seismic hazards. It indicated how there are concentrations of where people are killed by seismic hazards.\n• Figure 3c shows how the average number of deaths from seismic hazards follow the pattern of where plate margins are located, with concentrations in Central American and North India/around the Himalayas.\n• Figure 3d shows how countries with earthquake events with similar magnitude can have very different impacts in terms of the number of deaths and injuries.\n• Figure 3d shows information about the economic development of the country and the earthquake event from the USA has a much lower death and injury record than the events in Indonesia and Mexico.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2023-q3-p40.jpg", "figs": ["3c"]}, {"src": "2023-q3-p41.jpg", "figs": ["3d"]}]}, {"key": "2023R-3a", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify the natural hazard.", "intro": "", "options": [["A", "car emission pollution"], ["B", "nuclear meltdown"], ["C", "oil slick from a ship"], ["D", "volcanic eruption"]], "answer": "D", "type": "mcq", "lesson": "IGHZ01", "ms": "AO1 (1 mark)\n\nD volcanic eruption. (1).\n\nThe answer cannot be A, B or C as these are hazards created by human intervention.\n\n(1)", "sources": []}, {"key": "2023R-3bi", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify a factor that affects development of tropical cyclones.", "intro": "", "options": [["A", "large areas of high pressure"], ["B", "warm sea surface temperatures"], ["C", "an undersea earthquake"], ["D", "pyroclastic flows"]], "answer": "B", "type": "mcq", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\n\nB warm sea surface temperatures (1).\n\nThe answer cannot be A, C or D as these are not features associated with the development of cyclones.\n\n(1)", "sources": []}, {"key": "2023R-3bii", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one measure of tropical cyclone intensity.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following:\n\n• Saffir-Simpson scale (1)\n\n(1)", "sources": []}, {"key": "2023R-3biii", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(b)(iii)", "marks": 2, "text": "Explain how the Coriolis force affects tropical cyclones.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark) / AO2 (1 mark)\n\nAward 1 mark for an initial point, and a further mark for explanation or development.\n\n• Force created by the Earth’s rotation (1) that deflects moving objects at the Earth’s surface (1).\n\n• The deflection of the air moving along the surface of the Earth (1) rightward in the Northern Hemisphere / leftward in the Southern Hemisphere (1).\n\nAccept any other appropriate response. (2)", "sources": []}, {"key": "2023R-3c", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(c)", "marks": 3, "text": "Explain the formation of a constructive plate margin.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ03", "ms": "AO2 (3 mark)\n\nAward 1 mark for identification of a way and 2 marks for development and further explanation, up to a maximum of 3 marks.\n\n• Constructive plate margins form due to tectonic plate moving apart (1) this occurs due to hot magma under the earth’s crust rising due to convection currents (1) as the molten material rises it forms new land (1).\n\n• Divergent plate margins form where plates move away from each other (1) this occurs due to ridge push/slab pull (1) allowing magma to rise to fill the gap and solidify (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2023R-3d", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(d)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Suggest two short-term impacts of the earthquake shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ05", "ms": "AO2 (2 marks) / AO3 (2 marks)\n\nAward 1 mark (AO2) for identification of a short-term impact and a further mark (AO3) for further development shown on Figure 3a.\n\nCandidates should respond with two different factors, if responses just list two types of infrastructure damage limit to 1 mark max.\n\n• Infrastructure such as buildings and roads are destroyed (1) this may result in injury or death to the population (1).\n\n• Water supplies maybe damaged (1) which leads to the contamination of water and disease (1).\n\n• Need for medical supplies and aid (1) to cope with injuries caused by the earthquake (1).\n\n• Emergency relief (1) looking for trapped people (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2023R-q3-p37.jpg", "figs": ["3a"]}]}, {"key": "2023R-3e", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(e)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify the feature shown at X on the diagram.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ04", "ms": "AO3 (1 mark)\n\nAward 1 mark for one of the following.\n• Focus (1)\n\n(1)", "sources": [{"src": "2023R-q3-p38.jpg", "figs": ["3b"]}]}, {"key": "2023R-3f", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(f)", "marks": 4, "text": "Explain the long-term impacts of tropical cyclones.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ12", "ms": "AO1 / AO2 (4 marks)\n\nAward 1 mark for each initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks, or up to 2 marks for different initial points and a further mark for extension of these points up to a maximum of 4 marks.\n\nResponses could focus on explaining one particular impact or focus on more than one impact:\n\n• Road and rail links may be destroyed (1) meaning it is difficult to get longer term assistance to areas that are affected (1). This leads to a negative effect on economic growth (1) because countries take a long time to recover from the initial short- term effects (1).\n\n• Power cables may be destroyed (1) which may limit communication to coordinate responses (1). This can lead to more deaths if those injured are not treated (1) and can slow down the long term recovery of the area (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2023R-3g", "paper": "2023R", "paperLabel": "June 2023 · Paper 1R", "q": 3, "id": "3(g)", "marks": 8, "text": "Study Figure 3c and Figure 3d in the Resource Booklet. Analyse the reasons why people continue to live in areas prone to volcanic eruptions. Refer to the resources in your answer.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ10", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited.\n\nAO3\n• There are a wide variety of reasons why people live around volcanoes.\n• Tradition can play an important role for some cultures.\n• Volcanoes provide a valuable source of income. The income gained can help offset some of the risk that people face.\n• Many people regard the risk from the volcano as a natural part of life.\n\nAO4\n• Figure 3c shows subsistence farmers working in the shadow of the Volcano.\n• Figure 3c shows how in some countries Volcanoes provide a source of energy.\n• Figure 3d shows how rich countries are able to manage the risk of volcanoes through prediction and prevention.\n• Figure 3d shows how volcanoes provide a source of income at a national, local and individual level.\n• Figure 3d suggest for some people moving away from volcanoes is not an option due to their traditions or financial position.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)\nQuestion 4", "sources": [{"src": "2023R-q3-p39.jpg", "figs": ["3c", "3d"]}]}, {"key": "2022-3a", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify a type of plate boundary.", "intro": "", "options": [["A", "asymmetrical"], ["B", "constructive"], ["C", "hot spot"], ["D", "mantle"]], "answer": "B", "type": "mcq", "lesson": "IGHZ03", "ms": "AO1 (1 mark)\nB (Constructive)\n\nThe answer cannot be A (not a plate boundary), C (not found at a plate boundary) or D (part of the earth’s crust).\n(1)", "sources": []}, {"key": "2022-3bi", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify one characteristic of a tropical cyclone.", "intro": "", "options": [["A", "area of very high pressure"], ["B", "very little rainfall"], ["C", "low wind speeds"], ["D", "eye in the centre"]], "answer": "D", "type": "mcq", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\nD (eye in the centre)\nThe answer cannot be A (low pressure in a tropical cyclone),\nB (high rainfall), C (high wind speeds).\n(1)", "sources": []}, {"key": "2022-3bii", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one factor that can affect tropical cyclone formation.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\n\nAward 1 mark for a suitable factor:\n\n• (Warm sea surface) temperature (1)\n• Coriolis force (1)\n• Wind shear (1)\n• Converging winds (1)\n• Air pressure (1)\n• Latitude (1)\n• Climate / seasonality (1)\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "2022-3c", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(c)", "marks": 2, "text": "Explain one long-term impact of a tropical cyclone.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ12", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for identification of correct impact and a further mark for explanation (AO2) up to a maximum of two marks.\n• Damage to infrastructure (1) which requires heavy investment from the government (1).\n• Peoples’ homes are destroyed (1) so can lead to homelessness and development of makeshift settlements (1).\n• Damage to crops (1) which means farmers risk having no money to buy seeds for next season (1).\n\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2022-3d", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(d)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Explain two reasons why people continue to live in areas at risk from volcanoes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ10", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any reason and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• Serious eruptions may be considered to be rare (1) and so not considered a serious threat by residents (1).\n\n• Slopes of the volcano are very fertile (1) so many people remain to be involved in agriculture (1).\n\n• With so many settlements present people may have family connections (1) which they do not want to leave despite the risks (1).\n\n• Farming communities (typical in small settlements) as crops grow well (1) because soil is very fertile (1).\n• People may have no choice (1) as house prices might be cheaper (1).\n\nAccept any other appropriate response. (4)", "sources": [{"src": "2022-q3-p36.jpg", "figs": ["3a"]}]}, {"key": "2022-3e", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(e)", "marks": 3, "text": "Explain one way building design can help prepare for earthquakes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO2 (3 marks)\nAward 1 mark for the identification of a suitable reason and 2 marks for further explanation up to a maximum of 3 marks.\n\nCandidates could identify:\n• Building designs can ensure they are less likely to damage during an earthquake event (1) through steel frames that sway during the earth’s movement / rubber shock absorbers in foundations (1) which means it is less likely to create debris (1).\n• Buildings which were originally built without earthquakes in mind can be retrofitted (1) for example wire mesh to try and strengthen buildings (1) and reduce the number of buildings which would collapse (1).\n• Buildings can be designed with lightweight roofs or safety glass (1) so that they are less likely to break during an event (1) and so reduce the number of injuries (1).\n• Strict building codes (1) ensure buildings are built to reduce movement during an earthquake (1) making them less likely to collapse (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2022-3f", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(f)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify a potential short-term impact of the hazard shown.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Flooding (1)\n• Damage to buildings (1)\n• Power cuts (1)\n• Trees blown down (1)\n• Homelessness (1)\n• Deaths / injuries (1)\n• Habitats destroyed (1)\nAccept any other reasonable response linked to the resource.\n\n(1)", "sources": [{"src": "2022-q3-p37.jpg", "figs": ["3b"]}]}, {"key": "2022-3g", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(g)", "marks": 4, "text": "Explain how volcanoes are formed at a destructive plate boundary.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO1 (1 mark) AO2 (3 marks)\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks. Credit annotated diagrams where provided, but do not double credit ideas if repeated in the written text.\n\n• Oceanic and continental plates move towards each other (1). Oceanic plate melts as it sinks below the continental (1) as the temperature increases with depth in the Earth’s crust (1) this creates magma which rises through the continental crust to form a volcano (1).\n• Two tectonic plates move towards each other / meet (1) one is pushed under the other /subducted (1) and melts due to the heat within the Earth’s crust (1) and the resulting magma rises to the crust’s surface to form volcanoes (1).\n\nAccept any other appropriate response.\nAccept answers that use an annotated diagram.\n\n(4)\nQuestion Indicative Content", "sources": []}, {"key": "2022-3h", "paper": "2022", "paperLabel": "June 2022 · Paper 1", "q": 3, "id": "3(h)", "marks": 8, "text": "Study Figure 3c in the Resource Booklet. Analyse the hazard risk from this predicted distribution of tropical cyclones.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about analysing the pattern of vulnerability to tropical cyclones.\nAO3\n• Vulnerability to tropical cyclones is affected by the conditions that are needed for tropical cyclone formation.\n• Countries will be vulnerable at different times of year, depending on their location.\n• Climate change has been linked with higher frequency of tropical cyclones, and for a shift in where they are taking place. This means that there is the potential for a greater proportion of the world’s population to be at risk.\n• Hazard risk is a combination of the hazard (and its severity) and vulnerability. Many of the coastal areas in zone which have a high probability of a high intensity tropical storm have dense populations which increases the hazard risk.\n• Hazard frequency, and even intensity does not necessarily create high hazard risk. For example, those areas in the Pacific Ocean which do not have islands, the risk is low, compared to around the Philippines which have high population density and high probability of a storm up to 5 on the Saffir Simpson scale mean that hazard risk is high.\n\nAO4\n• Fig 3c shows how tropical storms can vary in intensity from 1-5 on the Saffir-Simpson scale.\n• Figure 3c shows area where there is a 10% probability of a storm striking, and the predicted intensity.\n• Figure 3c shows how there are large areas of South East Asia and Oceania which are highly vulnerable to tropical storms.\n• Figure 3c shows how the vulnerability is linked to seasonal changes for example in Bangladesh September to May being storm season.\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2022-q3-p38.jpg", "figs": ["3c"]}]}, {"key": "2021-3a", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify which of the following can be used to record earthquakes.", "intro": "", "options": [["A", "Flow meter"], ["B", "Hygrometer"], ["C", "Richter scale"], ["D", "Seismograph"]], "answer": "D", "type": "mcq", "lesson": "IGHZ04", "ms": "AO1 (1 mark)\nD (Seismograph) (1)\n\nThe answer cannot be A (measure for river speed), B (measures water vapour in the air), C (used to measure size of an earthquake).\n(1)", "sources": []}, {"key": "2021-3bi", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify a method of measuring tropical cyclones.", "intro": "", "options": [["A", "Bradshaw scale"], ["B", "Pressure scale"], ["C", "Saffir-Simpson scale"], ["D", "Wind speed scale"]], "answer": "C", "type": "mcq", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\n\nC (Saffir-Simpson scale) (1)\nThe answer cannot be A, B or D as these are incorrect.\n(1)", "sources": []}, {"key": "2021-3bii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one factor that influences the development of tropical cyclones.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following.\n\n• Warm air (1).\n• Moist air (1).\n• Warm sea (1).\n• Circular motion of air (1).\n• Around the equator/between the tropics (1).\n\nAccept any other appropriate response.\n(1)", "sources": []}, {"key": "2021-3biii", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(b)(iii)", "marks": 2, "text": "Explain one physical impact of a tropical cyclone hazard.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO1 (1 mark)/AO2 (1 mark)\nAward 1 mark (AO1) for identification of correct impact and a further mark for explanation (AO2) up to a maximum of two marks.\n• Destruction of buildings/infrastructure (1) caused by high winds (1).\n• Flooding (1) caused by associated heavy rain (1).\n• Storm surge (1) loss of life (1).\n• Trees blown down/destruction of habitats (1) causing damage or loss of life (1)\nAccept any other appropriate response.\n(2)", "sources": []}, {"key": "2021-3c", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(c)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Suggest two reasons why some places are more vulnerable to tectonic hazards than others.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ01", "ms": "AO2 (2 marks)/AO3 (2 marks)\n\nAward 1 mark (AO3) for identification of any reason from Fig 3a and a further mark for explanation of the reason (AO2) up to a maximum of two marks each.\n\n• Proximity to a plate boundary (1) increases likelihood of experiencing a hazard (1).\n• Megacities have high population densities (1) and therefore more people who may be impacted by a tectonic hazard event (1).\n• Some countries such as China have megacities located on plate boundaries (1) which means higher populations are at risk (1).\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2021-q3-p32.jpg", "figs": ["3a", "3b"]}]}, {"key": "2021-3d", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(d)", "marks": 3, "text": "Explain one strategy to reduce the impacts from earthquake events.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO2 (3 marks)\n\nAward 1 mark for the identification of a strategy which could reduce risk from the impacts of an earthquake event and 2 marks for further explanation up to a maximum of 3 marks.\n\nCandidates could identify:\n• Early warning systems (1) to allow people evacuate (1) which could reduce deaths (1).\n• Building earthquake resistant buildings/example of approach (counter weight / Concrete exoskeleton) (1) to reduce damage from ground shaking (1) which should result in less injuries (1).\n• Practicing earthquake drills (1) so people know how to correctly respond to an earthquake event (1) which should reduce the risk of injury (1).\n\nAccept any other appropriate response.\n\n(3)", "sources": []}, {"key": "2021-3e", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(e)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify the type of plate boundary.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ03", "ms": "AO3 (1 mark)\nAward 1 mark for the following:\n• Conservative / transform (1)\n\n(1)", "sources": [{"src": "2021-q3-p32.jpg", "figs": ["3a", "3b"]}]}, {"key": "2021-3f", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(f)", "marks": 4, "text": "Explain the formation of a volcano.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO1 (1 mark) AO2 (3 marks)\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks.\n\n1+1 and 1+1 or 1+1+1+1\n• On a destructive plate margin two plates push together until one is subducted (1). As the plate is pushed down the rock melts (1) and builds up pressure under the earths surface (1). Lava is ejected and cools to form a layer of a volcano (1).\n• On a destructive plate margin one plate is subducted under the other (1) which means that molten magma is released (1) and rises to surface (1).\n• However at a constructive plate margin plates moves apart (1) and magma rises up to fill the gap (1) and erupts at surface as a volcano (1).\n\nCandidates may also focus on volcano formation at constructive plate margins or hot spots.\n\nAnnotated diagrams are acceptable but must explain the process and ensure there is no double reward.\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2021-3g", "paper": "2021", "paperLabel": "Summer 2021 · Paper 1", "q": 3, "id": "3(g)", "marks": 8, "text": "Study Figure 3c in the Resource Booklet. Analyse the short- and long-term impacts of the earthquake event.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ05", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level-based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive, and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about analysing the difference between the short- and long-term impacts of the earthquake event.\n\nAO3\n• There are a range of short- and long-term impacts of earthquakes which can vary due to the size and intensity of the earthquake as well as the location.\n• Short-term impacts which occur as a result of ground shaking are often very destructive causing buildings to collapse for example, transport and communication links being disrupted, with the results including injury and death.\n• Long-term impacts which occur as a result of the damage made by the earthquake event can have a large impact on society as they have the potential to put a large strain on society. For example, when large numbers of people lose their homes, or water supplies are contaminated.\n• The level of impact can be influenced by the level of development of the country and its ability to respond to short term impact and as a result the longer-term response to the hazardous event.\n• The level of intervention from outside agencies/national government will have a direct influence on the ability to reduce the impacts of the hazardous event.\n• The location and accessibility can also affect the ability to reduce impacts in both the long and short-term.\nAO4\n• Fig 3c shows a map of perceived shaking in the Haiti 2010 earthquake. It shows how there was a large area of perceived extreme shaking in Port-au-Prince.\n• Figure 3c suggests shows that the short-term impacts affected a large amount of people (220,000 people killed/ 300,000 injured).\n• Figure 3c indicates how there were serious longer-term impacts which will have also affected a large amount of the population, particularly given the Figure shows that large percentages of some cities were destroyed.\n• Figure 3c indicates how some of these impacts could include the shortage of aid supplies and outbreaks of cholera.\n• Figure 3c shows the high magnitude of the earthquake.\n• Figure 3c suggests a high level of disruption to infrastructure.\n\nCandidates may use compass bearings and scale to support their response.\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2021-q3-p33.jpg", "figs": ["3c"]}]}, {"key": "2019-3a", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify the statement below that best describes the epicentre of an earthquake.", "intro": "", "options": [["A", "the area around the earthquake on the surface"], ["B", "the point on the Earth’s surface directly above the focus"], ["C", "the area around the earthquake underground"], ["D", "the location underground where the earthquake occurs"]], "answer": "B", "type": "mcq", "lesson": "IGHZ04", "ms": "AO1 (1 mark)\n\nB the point on the earth’s surface directly above the focus\n\nA, C, D are incorrect because they are not directly above the focus\n\n(1)", "sources": []}, {"key": "2019-3bi", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "State one measure of earthquake intensity.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ04", "ms": "AO1 (1 mark)\nAward 1 mark for any of the following:\n\n• Mercalli scale (1)\n\nAlso accept:\n\n• Moment Magnitude scale / MM / MMI / MMS (1)\n\n• Richter scale (1)\n\nDo not accept:\n\n• seismograph / seismometer\n• impacts of earthquakes e.g. damage to buildings, deaths etc.\n\n(1)", "sources": []}, {"key": "2019-3bii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one characteristic of a volcanic eruption.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following:\n\n• lava (1)\n\n• ash clouds (1)\n\n• gas emissions (1)\n\n• lava bombs (1)\n\n• earthquakes / tremors (1)\n\n• pyroclastic flow (1)\n\n• mudslide / mass movement (1)\n\nAccept any other appropriate response. (1)", "sources": []}, {"key": "2019-3biii", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(b)(iii)", "marks": 2, "text": "Explain one cause of an earthquake event.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ04", "ms": "AO1 (1 mark)/AO2 (1 mark)\n\nAward 1 mark (AO1) for a point about a cause of an earthquake and 1 mark (AO2) for further explanation, up to a maximum of 2 marks.\nA sudden tremor of the earth’s crust (1) caused by tectonic ac- tivity at plate margins and faults (1)\n\nEarthquakes are caused by built up pressure inside the earths’ crust (1) which is released when tectonic plates move (1)\n\nAccept any other appropriate response, including those refer- ring to fracking, nuclear testing and volcanic eruptions.\n\n(2)", "sources": []}, {"key": "2019-3c", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(c)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Suggest a factor that influences the cause and another factor that influences the direction of tropical cyclones.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO2 (2 mark)/AO3 (2 mark)\n\nAward 1 mark (AO2) for the identification of an idea from the map in fig 3a and a further mark (AO3) for further development, shown on Figure 3a, Candidates should respond with one cause and one di- rection. Cause Warm sea temperatures (1) Tropical cyclones tend to develop where temperatures are above 27 degrees (1) Low air pressure (1) which pulls water high as the cyclone gath- ers speed (1) Direction Tropical cyclones move in the direction of the prevailing wind (1) these are common wind directions caused by convection currents / earth’s rotation / Coriolis Effect / Trade Winds (1)\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2019-q3-p38.jpg", "figs": ["3a"]}]}, {"key": "2019-3d", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(d)", "marks": 3, "text": "Explain one way earthquakes can form tsunamis.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ05", "ms": "(3)\nAO2 (3 marks)\n\nAward 1 mark for identification of a way and 2 marks for develop- ment and further explanation, up to a maximum of 3 marks.\n\nEarthquakes under the sea bed form shock waves (1) this forms a wave which splits (1). The wave then gets bigger (amplifying) and hits the shore (1)\n\nTectonic plate movement can trigger an underwater earth- quake (1) which causes tremors under water causing waves (1) the waves can increase in height over a large distance (1)\n\nAccept any other appropriate response", "sources": []}, {"key": "2019-3e", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(e)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify one feature of this building that makes it more tsunami resistant.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ05", "ms": "AO3 (1 mark)\n\nAward 1 mark for the following.\n\nThe building is on stilts (1)\n\nThe building is off the ground (1)\n\nIdea of strong / reinforced base (1)\n\nShatterproof windows (1)\n\nAccept any other appropriate response.\n\n(1)", "sources": [{"src": "2019-q3-p39.jpg", "figs": ["3b"]}]}, {"key": "2019-3f", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(f)", "marks": 4, "text": "Explain why some countries are more vulnerable than others to the impacts of natural hazards.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ01", "ms": "AO1 (1 mark)/AO2 (3 mark)\n\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks.\n\n1+1+1+1 2+2 3+1\n\nLack of education (1) meaning people don’t know what to do (1). Lack of emergency planning (1) meaning when the event occurs there is little or no response in a short period of time (1) Low level of economic development (1) meaning there is no re- source available to respond (1) resulting in chaos and panic when the event occurs (1) and a lack of resource to rebuild (1)\n\nSome countries experience a high frequency of natural hazards (1) which means that they do not have enough time / money to respond sufficiently (1) so additional money needs to be spent on recovery (1) which limits opportunity for increasing the level of development (1)\n\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2019-3g", "paper": "2019", "paperLabel": "June 2019 · Paper 1", "q": 3, "id": "3(g)", "marks": 8, "text": "Study Figure 3c and Figure 3d in the Resource Booklet. Analyse the use of hazard, vulnerability and risk mapping in reducing the impact of earthquakes.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited. This question is about investigating the issue of why hazard mapping can be use- ful in managing earthquake risk. Candidates could explore the use of hazard mapping before, during and after an earthquake event. Use of both resources needed for level 3\nAO3\n• Hazard/vulnerability/risk maps can be used in a variety of ways before, during and after a hazardous event.\n• Candidates should examine how the use of Hazard maps can impact against impacts\n• Road structures identified through hazard maps could be used to enable emergency aid to get to an earthquake zone more quickly enabling the re- lief effort to start.\n• Hazard maps shared with all support agencies can enable a more coordi- nated relief effort ensuring resources are not wasted /deployed in the wrong area.\n• Using hazard maps can help plan in the short term where services where before and where they can be built afterwards\nAO4\n• Fig 3c shows stages in the process of hazard mapping\n• Fig 3c data can be collected on hazard events to help develop strategies to reduce the impact of earthquakes, for example understanding areas where they happen frequently\n• Fig 3c data can be presented and shared across a wide variety of organi- sations to help them plan better for hazard events\n• Fig 3c assessments can be made to identify trends and patterns in hazard data and present in the form of vulnerability and risk maps\n• Fig 3c data can be used to inform land zoning\n• Fig 3d shows Hazard, vulnerability and risk\n• Fig 3d shows there is a positive correlation between the three maps\n• Fig 3d shows that as the hazard risk rises so does vulnerability generally\n• Fig 3d shows that in some cases even though risk is high vulnerability is only moderate\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but un- derstanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judge- ments that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited rele- vance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well-devel- oped argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2019-q3-p40.jpg", "figs": ["3c"]}, {"src": "2019-q3-p41.jpg", "figs": ["3d"]}]}, {"key": "2019R-3a", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(a)", "marks": 1, "text": "Identify the statement below that best describes a destructive (convergent) plate margin.", "intro": "", "options": [["A", "the plates pull apart and magma rises"], ["B", "the plates push together and both plates are destroyed"], ["C", "the plates pull apart and volcanoes erupt"], ["D", "the plates push together and one plate is destroyed"]], "answer": "D", "type": "mcq", "lesson": "IGHZ03", "ms": "AO1 (1 mark)\n\nD is the correct response - plates push together and one plate is destroyed.\n\nA and C are not correct as they describe constructive plate margins\n\nB is not correct s it is not an accurate description\n\n(1)", "sources": []}, {"key": "2019R-3bi", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(b)(i)", "marks": 1, "text": "Identify one measurement of a volcanic hazard.", "intro": "", "options": [["A", "Volcanic Mercalli Scale"], ["B", "Volcanic Saffir-Simpson Scale"], ["C", "Volcanic Explosivity Index"], ["D", "Volcanic Eruption Source"]], "answer": "C", "type": "mcq", "lesson": "IGHZ09", "ms": "AO1 (1 mark)\n\nC is the correct response - Volcanic Explosivity index\n\nA, B and D are all inaccurate measures of volcanic hazards\n\n(1)", "sources": []}, {"key": "2019R-3bii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(b)(ii)", "marks": 1, "text": "State one human factor that affects the impact of a tectonic hazard.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ01", "ms": "AO1 (1 mark)\n\nAward 1 mark for any of the following:\n\n• Education / knowledge / awareness (1)\n• Emergency plan / warning systems / prediction / management (1)\n• (Level / quality) of infrastructure (1)\n• Age / quality / strength of buildings (1)\n• (Level of) development (1)\n• Population density / population age (1)\n• Land-use (1)\n\n(1)\nAccept any other appropriate response.\n\nReject population without any context, e.g. age", "sources": []}, {"key": "2019R-3biii", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(b)(iii)", "marks": 2, "text": "Explain one physical impact of a volcanic eruption.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ09", "ms": "AO1 (1 mark)/AO2 (1 mark)\n\nAward 1 mark (AO1) for the identification of a physical impact (1) and 1 mark (AO2) for further explanation, up to a maximum of 2 marks.\n• Ash from the volcano is ejected into the atmosphere (1) the ash causes physical damage to property and agricultural land (1)\n• Lava flows ejected from the volcano can travel up to 10km (1) destroying buildings and agricultural land (1)\n• Impact ash from the volcano mixes with mud and water (1) creating a mudflow which destroys building and farmland (1)\n\nAccept any other appropriate response\n\n(2)", "sources": []}, {"key": "2019R-3c", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(c)", "marks": 4, "text": "Study Figure 3a in the Resource Booklet. Suggest two factors that influence the distribution of a tropical cyclone.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ11", "ms": "AO2 (2 mark)/AO3 (2 mark)\n\nAward 1 mark (AO2) for identification of how a factor could affect the distribution and a further mark (AO3) for further development shown on Figure 3a. Candidates should respond with two different factors.\n\n• Sea temperatures – Tropical cyclones tend to develop where temperatures are higher 24-27 degrees (1) this means that convection currents will be high enough to maintain the cyclone vortex (1)/provides energy to feed the cyclone.\n• Cyclones tend to develop in the tropics (1) as this where the temperature and humidity are highest (1)\n• Low air pressure pulls wind in and increasing intensity (1) this churns up the water developing the cyclone (1)\n• Strong winds caused by the Coriolis effect (1) gives a tropical cyclone its rotation anticlockwise in the northern hemisphere (1)\n\nAccept any other appropriate response.\n\n(4)", "sources": [{"src": "2019R-q3-p38.jpg", "figs": ["3a"]}]}, {"key": "2019R-3d", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(d)", "marks": 3, "text": "Explain one way a hotspot can lead to a tectonic hazard.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ10", "ms": "AO3 (3 marks)\n\nAward 1 mark for identification of a way and 2 marks for development and further explanation, up to a maximum of 3 marks.\n\n• Hotspots – this is a point at which material from deep inside the earth’s mantle (1) is pushed to the surface by convection currents (1) as this material breaks through the earth’s crust it forms volcanoes which can lead to physical and human impacts (1)\n\n• Hot spots are plumbs of magma (1) that are pushed through a weakness in the earth’s crust (1) to form volcanoes (1)\n\n(3)", "sources": []}, {"key": "2019R-3e", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(e)", "marks": 1, "text": "Study Figure 3b in the Resource Booklet. Identify the building design characteristic in Box X that makes this building more resistant to collapse.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO3 (1 mark)\n\nAward 1 mark for one of the following.\n• Cross bracing (1)\n• Reinforced concrete (1)\n• Concrete exoskeleton (1)\n• Strong foundations (1)\n\nAccept any other appropriate response.\n\n(1)", "sources": [{"src": "2019R-q3-p39.jpg", "figs": ["3b"]}]}, {"key": "2019R-3f", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(f)", "marks": 4, "text": "Explain why people live in areas at risk from hazardous events.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO1 (1 mark)/AO2 (3 mark)\n\nAward 1 mark for initial point (AO1), and 3 further marks (AO2) for the extension of this point up to maximum of 4 marks. Responses could include:\n• Lack of education (1) so they don’t know any better / poor decision-makers (1).\n• Always lived at the location and don’t think it will happen to them (1) so there is and acceptance of risk (1).\n• Economic reasons meaning they can’t afford to move (1) and worry about not being able to find a job elsewhere (1).\n• Where they live is a highly developed areas (1) may not want to move away tradition / family / they have made and investment of time and money (1).\nAccept any other appropriate response.\n\n(4)", "sources": []}, {"key": "2019R-3g", "paper": "2019R", "paperLabel": "June 2019 · Paper 1R", "q": 3, "id": "3(g)", "marks": 8, "text": "Study Figure 3c and Figure 3d in the Resource Booklet. Analyse the use of GIS in managing earthquake risk.", "intro": "", "options": [], "answer": null, "type": "write", "lesson": "IGHZ06", "ms": "AO3 (4 marks) AO4 (4 marks)\n\nMarking instructions Markers must apply the descriptors in line with the general marking guidance and the qualities outlined in the level based mark scheme below.\n\nIndicative content guidance The indicative content below is not prescriptive and candidates are not required to include all of it. Other relevant material not suggested below must also be credited.\n\nUse of both resources needed for level 3\nAO3\n• GIS can be used in a variety of ways before during and after a hazardous event.\n• Candidates should examine how the use of GIS can impact against elements identified in Figure 3c.\n• Road structures identified through GIS could be used to enable emergency aid to get to an earthquake zone more quickly enabling the relief effort to start.\n• Coordinated GIS maps shared with all support agencies can enable a more coordinated relief effort ensuring resources are not wasted /deployed in the wrong area.\n• Using GIS can help plan in the short term where services where before and where they can be built afterwards\n• Candidates will outline the immediate short term and longer term effects of the disaster event and outline how this affects QOL\nAO4\n• Fig 3c shows how quality of life changes in response to a disaster event\n• Fig 3c shows that initially after the disaster event the quality of life/economic activity and social stability goes down\n• Fig 3c as relief arrives these begin to increase back to normal levels over time\n• Fig 3d provides a variety of ways in which GIS can be used to support earthquake response\n\n• Fig 3d outlines the stages that can be used to develop an understanding of hazard management\n• Fig 3d suggests the correct way planners should use data to support emergency management\n\nLevel Mark Descriptor\n\n0 No rewardable material.\n\nLevel 1 1–3 • Attempts to apply understanding to deconstruct information but understanding and connections are flawed. An unbalanced or incomplete argument that provides limited synthesis of understanding. Judgements that are supported by limited evidence. (AO3)\n\n• Uses some geographical skills to obtain information with limited relevance and accuracy, which supports few aspects of the argument. (AO4)\n\nLevel 2 4–6 • Applies understanding to deconstruct information and provide some logical connections between concepts. An imbalanced argument that synthesises mostly relevant understanding, but not entirely coherently, leading to judgements that are supported by evidence occasionally. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports some aspects of the argument. (AO4)\n\nLevel 3 7–8 • Applies understanding to deconstruct information and provide logical connections between concepts throughout. A balanced, well- developed argument that synthesises relevant understanding coherently, leading to judgements that are supported by evidence throughout. (AO3)\n\n• Uses geographical skills to obtain accurate information that supports all aspects of the argument. (AO4)", "sources": [{"src": "2019R-q3-p40.jpg", "figs": ["3c"]}, {"src": "2019R-q3-p41.jpg", "figs": ["3d"]}]}]};
